INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(130464, 'ruRU', '', 'Тема сегодняшнего соревнования... Эпический фиолетовый!', 24330),
(130465, 'ruRU', '', 'Тема сегодняшнего соревнования... Защитники Света!', 24330),
(130466, 'ruRU', '', 'Тема сегодняшнего соревнования... Вольный стиль!', 24330),
(130510, 'ruRU', '', 'Я хочу трансмогрифицировать своё снаряжение.', 24330),
(130512, 'ruRU', '', 'Я хочу принять участие в Испытании стиля!', 24330),
(130515, 'ruRU', '', 'Sound effect for troops', 24330),
(130517, 'ruRU', '', 'Sound effect for troops', 24330),
(130590, 'ruRU', '', '|TInterface\\Icons\\SPELL_ARCANE_INVOCATION.BLP:20|tНа тебя наложен |cFFFF0000|Hspell:236712|h[Лунный маяк]|h|r!', 24330),
(130591, 'ruRU', '', '|TInterface\\Icons\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t%s направляет на тебя |cFFFF0000|Hspell:236603|h[Быстрый выстрел]|h|r!', 24330),
(130605, 'ruRU', '', '|TInterface\\Icons\\SPELL_NATURE_MOONGLOW.BLP:20|tНа тебя воздействует |cFFFF0000|Hspell:236519|h[Лунный ожог]|h|r!', 24330),
(130612, 'ruRU', '', '|TInterface\\Icons\\artifactability_BalanceDruid_FullMoon.blp:20|t |cFFFF0000|Hspell:236357|h[Источник Элуны]|h|r достиг полной луны.', 24330),
(130613, 'ruRU', '', '|TInterface\\Icons\\artifactability_BalanceDruid_NewMoon.blp:20|t |cFFFF0000|Hspell:236357|h[Источник Элуны]|h|r достиг новой луны.', 24330),
(130642, 'ruRU', '', 'Я никогда не стану доверять Предателю или его прислужникам-иллидари, но готов отложить свои сомнения ради общего блага.\n\nНо когда Легион падёт, какая польза будет нам от тех, кто отмечен его порчей?', 24330),
(130644, 'ruRU', '', 'Я понимаю, что это не особо похоже на трактир, но это всё, что у нас есть.', 24330),
(130647, 'ruRU', '', '$ct, видишь что-то, что тебе нравится?', 24330),
(130666, 'ruRU', '', 'Мои стражи удерживают Собор, но всё это будет напрасно, если Килджеден пробудит павшую аватару своего хозяина в глубинах Гробницы.\n\nПохоже, Иллидан и его последователи всё ещё нужны... пока что.', 24330),
(130767, 'ruRU', '', 'Давайте позовём Отрекшихся на сцену!', 24330),
(130768, 'ruRU', '', 'Время Отрекшимся танцевать. Их движения захватят дух.', 24330),
(130769, 'ruRU', '', 'Выходите, тролли! Покажите всем, как это делается!', 24330),
(130770, 'ruRU', '', 'Время для тролльего танца! Никакая обувь не удержит эти ноги!', 24330),
(130771, 'ruRU', '', 'Берегите ноги! Время тауренского танца, а эти копыта могут сделать больно.', 24330),
(130772, 'ruRU', '', 'Выходите, таурены! Покажите, как это делают в Мулгоре.', 24330),
(130773, 'ruRU', '', 'Давайте позовём этих гоблинов на сцену, чтобы все их увидели!', 24330),
(130774, 'ruRU', '', 'Покажите мне эти гоблинские движения!', 24330),
(130775, 'ruRU', '', 'Насладитесь прекрасными движениями эльфов крови!', 24330),
(130776, 'ruRU', '', 'Эльфы крови! Ваша очередь танцевать.', 24330),
(130777, 'ruRU', '', 'Люблю смотреть, как пандарены раскачивают свой вес. Время танцевать!', 24330),
(130778, 'ruRU', '', 'Выходите, пандарены!', 24330),
(130779, 'ruRU', '', 'Поднимайтесь, сёстры и братья орки! Покажите свои движения!', 24330),
(130780, 'ruRU', '', 'Это наш город, орки. Покажем им нашу гордость!', 24330),
(130783, 'ruRU', '', 'Поверить не могу, что они захватили всё здание только для танцевальной вечеринки! Где мне теперь продавать все эти штаны?', 24330),
(130785, 'ruRU', '', 'Ох. Точно.', 24330),
(130802, 'ruRU', '', 'В атаку, мои красавчики!', 24330),
(130831, 'ruRU', '', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|tНе найдя душ в Материальном мире, Машина Душ обрушивается с помощью |cFFFF0000|Hspell:236507|h[Покоя]|h|r!', 24330),
(131034, 'ruRU', '', 'Это ваш город, люди. Покажите нам свою гордость!', 24330),
(131035, 'ruRU', '', 'Слышал слух, что люди не умеют танцевать. Докажите, что я ошибаюсь!', 24330),
(131036, 'ruRU', '', 'Смотрите, как двигаются эти дворфийские ноги! И всё это без того, чтобы разлить своё эль!', 24330),
(131037, 'ruRU', '', 'Время дворфам показать нам, как они веселятся!', 24330),
(131038, 'ruRU', '', 'Насладитесь стройными, уверенными ночными эльфами! Я скоро начну задыхаться...', 24330),
(131039, 'ruRU', '', 'Ночные эльфы! Покажите, как вы отплясываете у себя в Тельдрассиле!', 24330);
